require_once __DIR__.'/functions.php';$token=$_GET['token']??'';if(!is_string($token)||!preg_match('/^[a-f0-9]{48}$/',$token)){http_response_code(404);exit('Link tidak valid.');}$s=db()->prepare('SELECT f.* FROM shares sh JOIN files f ON f.id=sh.file_id WHERE sh.token_hash=? AND sh.expires_at>NOW()');$s->execute([hash('sha256',$token)]);$f=$s->fetch();if(!$f){http_response_code(404);exit('Link tidak ditemukan atau sudah kedaluwarsa.');}$path=STORAGE_DIR.'/'.$f['stored_name'].'.enc';if(!is_file($path)){http_response_code(404);exit('File tidak ditemukan.');}try{$plain=decrypt_file(file_get_contents($path));}catch(Throwable $e){http_response_code(500);exit('File tidak dapat dibuka.');}header('Content-Type: application/octet-stream');header('Content-Length: '.strlen($plain));header('Content-Disposition: attachment; filename="'.rawurlencode($f['original_name']).'"');header('X-Content-Type-Options: nosniff');echo $plain;
